class Solution {
    public int maxEnvelopes(int[][] envelopes) {
        java.util.Arrays.sort(envelopes, (a, b) -> a[0] != b[0]
                ? Integer.compare(a[0], b[0])
                : Integer.compare(b[1], a[1]));
        int[] tails = new int[envelopes.length];
        int size = 0;
        for (int[] envelope : envelopes) {
            int position = lowerBound(tails, size, envelope[1]);
            tails[position] = envelope[1];
            if (position == size) {
                size++;
            }
        }
        return size;
    }

    private int lowerBound(int[] values, int length, int target) {
        int left = 0;
        int right = length;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (values[mid] < target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }
}

class Solution {
    public int maxEnvelopes(int[][] envelopes) {
        java.util.Arrays.sort(envelopes, (a, b) -> a[0] != b[0]
                ? Integer.compare(a[0], b[0])
                : Integer.compare(a[1], b[1]));
        int n = envelopes.length;
        int[] dp = new int[n];
        java.util.Arrays.fill(dp, 1);
        int answer = 1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < i; j++) {
                if (envelopes[j][0] < envelopes[i][0] && envelopes[j][1] < envelopes[i][1]) {
                    dp[i] = Math.max(dp[i], dp[j] + 1);
                }
            }
            answer = Math.max(answer, dp[i]);
        }
        return answer;
    }
}

class Solution {
    public int maxEnvelopes(int[][] envelopes) {
        java.util.Arrays.sort(envelopes, (a, b) -> a[0] != b[0]
                ? Integer.compare(a[0], b[0])
                : Integer.compare(b[1], a[1]));
        int[] heights = compressedHeights(envelopes);
        Fenwick fenwick = new Fenwick(heights.length + 2);
        int answer = 0;
        for (int[] envelope : envelopes) {
            int rank = lowerBound(heights, envelope[1]) + 1;
            int best = fenwick.query(rank - 1) + 1;
            fenwick.update(rank, best);
            answer = Math.max(answer, best);
        }
        return answer;
    }

    private int[] compressedHeights(int[][] envelopes) {
        int[] heights = new int[envelopes.length];
        for (int i = 0; i < envelopes.length; i++) {
            heights[i] = envelopes[i][1];
        }
        java.util.Arrays.sort(heights);
        int unique = 0;
        for (int height : heights) {
            if (unique == 0 || heights[unique - 1] != height) {
                heights[unique++] = height;
            }
        }
        return java.util.Arrays.copyOf(heights, unique);
    }

    private int lowerBound(int[] values, int target) {
        int left = 0;
        int right = values.length;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (values[mid] < target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }

    private static class Fenwick {
        private final int[] tree;

        Fenwick(int size) {
            tree = new int[size + 1];
        }

        void update(int index, int value) {
            for (int i = index; i < tree.length; i += i & -i) {
                tree[i] = Math.max(tree[i], value);
            }
        }

        int query(int index) {
            int best = 0;
            for (int i = index; i > 0; i -= i & -i) {
                best = Math.max(best, tree[i]);
            }
            return best;
        }
    }
}

class Solution {
    private int[] tree;
    private int size;

    public int maxEnvelopes(int[][] envelopes) {
        java.util.Arrays.sort(envelopes, (a, b) -> a[0] != b[0]
                ? Integer.compare(a[0], b[0])
                : Integer.compare(b[1], a[1]));
        int[] heights = compressedHeights(envelopes);
        size = 1;
        while (size < heights.length + 2) {
            size <<= 1;
        }
        tree = new int[size * 2];
        int answer = 0;
        for (int[] envelope : envelopes) {
            int rank = lowerBound(heights, envelope[1]) + 1;
            int best = query(1, rank - 1) + 1;
            update(rank, best);
            answer = Math.max(answer, best);
        }
        return answer;
    }

    private int[] compressedHeights(int[][] envelopes) {
        int[] heights = new int[envelopes.length];
        for (int i = 0; i < envelopes.length; i++) {
            heights[i] = envelopes[i][1];
        }
        java.util.Arrays.sort(heights);
        int unique = 0;
        for (int height : heights) {
            if (unique == 0 || heights[unique - 1] != height) {
                heights[unique++] = height;
            }
        }
        return java.util.Arrays.copyOf(heights, unique);
    }

    private int lowerBound(int[] values, int target) {
        int left = 0;
        int right = values.length;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (values[mid] < target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }

    private void update(int rank, int value) {
        int index = rank + size - 1;
        tree[index] = Math.max(tree[index], value);
        index >>= 1;
        while (index > 0) {
            tree[index] = Math.max(tree[index * 2], tree[index * 2 + 1]);
            index >>= 1;
        }
    }

    private int query(int left, int right) {
        if (left > right) {
            return 0;
        }
        int best = 0;
        int l = left + size - 1;
        int r = right + size - 1;
        while (l <= r) {
            if ((l & 1) == 1) {
                best = Math.max(best, tree[l++]);
            }
            if ((r & 1) == 0) {
                best = Math.max(best, tree[r--]);
            }
            l >>= 1;
            r >>= 1;
        }
        return best;
    }
}

class Solution {
    public int maxEnvelopes(int[][] envelopes) {
        java.util.Arrays.sort(envelopes, (a, b) -> a[0] != b[0]
                ? Integer.compare(a[0], b[0])
                : Integer.compare(a[1], b[1]));
        int[] heights = compressedHeights(envelopes);
        Fenwick fenwick = new Fenwick(heights.length + 2);
        int answer = 0;
        int index = 0;
        while (index < envelopes.length) {
            int next = index;
            while (next < envelopes.length && envelopes[next][0] == envelopes[index][0]) {
                next++;
            }
            int[] ranks = new int[next - index];
            int[] values = new int[next - index];
            for (int i = index; i < next; i++) {
                int rank = lowerBound(heights, envelopes[i][1]) + 1;
                ranks[i - index] = rank;
                values[i - index] = fenwick.query(rank - 1) + 1;
                answer = Math.max(answer, values[i - index]);
            }
            for (int i = 0; i < ranks.length; i++) {
                fenwick.update(ranks[i], values[i]);
            }
            index = next;
        }
        return answer;
    }

    private int[] compressedHeights(int[][] envelopes) {
